    <script>
    "use strict";
    (function($) {
        const formatSelection = (state) => {
            if (!state.id) {
                return state.text;
            }
            return `+${state.element.dataset.mobile_code}`;
        }

        const selectedCountry = $(`[data-code=IN]`).val();

        $('#loginAndGuestModal select[name=country]').val(selectedCountry).select2({
            dropdownParent: $('#loginAndGuestModal select[name=country]').parent(),
            templateSelection: formatSelection
        });

        $('#loginAndGuestModal select[name=country]').on('change', function() {
            $('input[name=mobile_code]').val($('select[name=country] :selected').last().data(
            'mobile_code'));
            $('input[name=country_code]').val($('select[name=country] :selected').last().data('code'));
            $('.mobile-code').text('+' + $('select[name=country] :selected').last().data('mobile_code'));
        });

        $('input[name=mobile_code]').val($('select[name=country] :selected').data('mobile_code'));
        $('input[name=country_code]').val($('select[name=country] :selected').data('code'));
        $('.mobile-code').text('+' + $('select[name=country] :selected').data('mobile_code'));
    })(jQuery);
    </script>
    <script>
    (function($) {
        "use strict";


        function showRecentlyViewed() {
            const config = {
                days: 7,
                limit: 12
            };

            let viewedProducts = JSON.parse(localStorage.getItem("recentlyViewed")) || [];
            let recentViewSection = $(".recently-viewed-section");
            let recentViewContainer = $(".recent-view");
            let now = new Date().getTime();
            let maxAge = config.days * 24 * 60 * 60 * 1000;

            recentViewContainer.empty();

            // Filter by age
            viewedProducts = viewedProducts.filter(product => now - product.date < maxAge);

            // Limit number of items
            viewedProducts = viewedProducts.slice(0, config.limit);

            if (viewedProducts.length > 0) {
                viewedProducts.forEach(function(product) {
                    let productHtml = `
                        <div class="product-card">
                            <div class="product-thumb">
                                <a href="${product.plink}">
                                    <img src="${product.pima}" alt="${product.pna}">
                                </a>
                            </div>
                            <div class="product-content">
                                <h6 class="title">
                                    <a href="${product.plink}">${product.pna}</a>
                                </h6>
                            </div>
                        </div>
                    `;
                    recentViewContainer.append(productHtml);
                });
                localStorage.setItem("recentlyViewed", JSON.stringify(viewedProducts));
            } else {
                recentViewSection.remove();
            }
        }

        showRecentlyViewed();
    })(jQuery);
    </script>
